var EXTRA=[{"dot": "gray", "j": "J Orthop Case Rep", "h": "Matrice di collagene acellulare su difetti condrali ampi: descrizione di due casi", "v": "Case report con mappa T2 a sei mesi e punteggi in rialzo, senza gruppo di confronto: valore aneddotico. Concettualmente vicina alla membrana dell'AMIC, ma l'abstract non nomina il prodotto.", "pmid": "42851910", "doi": "10.13107/jocr.2026.v16.i10.8186", "temi": ["cartilagine", "matrice di collagene", "caso clinico"]}, {"dot": "gray", "j": "J Orthop Case Rep", "h": "Allineamento cinematico contro meccanico nella TKA: la TC dinamica vede una rotula più centrata", "v": "Studio prospettico comparativo monocentrico indiano, gruppi piccoli e criterio di assegnazione non descritto nell'abstract: segnale a favore del cinematico su tracking rotuleo e dolore anteriore, da confermare con un RCT.", "pmid": "42851691", "doi": "10.13107/jocr.2026.v16.i10.8340", "temi": ["protesi totale di ginocchio", "allineamento", "rotula"]}, {"dot": "gray", "j": "J Athl Train", "h": "Prontezza psicologica dopo LCA: a sei mesi pesano ansia e paura del movimento più della forza", "v": "Studio trasversale su atleti giovani: ansia generalizzata, cinesiofobia e qualità di vita spiegano gran parte dell'ACL-RSI, forza e salti poco. Campione piccolo, un solo momento, nessun esito di rientro.", "pmid": "42852171", "doi": "10.4085/1062-6050-0696.25", "temi": ["LCA", "rientro allo sport", "paura del movimento"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Sonnery-Cottet: un'ansa di seta per passare l'innesto dell'ALL fra i due tunnel tibiali", "v": "Nota tecnica senza pazienti: spingi-nodo e seta sostituiscono l'ago cieco nel sottocute. Idea semplice, nessun dato di esito.", "pmid": "42852393", "doi": "10.1002/atn2.70305", "temi": ["ALL", "Sonnery-Cottet", "nota tecnica"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Tunnel femorale ovale nel LCA: la tecnica Fujian Union", "v": "Nota tecnica che descrive un dilatatore ovale per riprodurre l'impronta anatomica; nessun risultato clinico nell'abstract.", "pmid": "42852099", "doi": "10.1002/atn2.70271", "temi": ["LCA", "tunnel femorale", "nota tecnica"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "TKA non cementata stampata in 3D contro la stessa cementata: meno risultati peggiori sul Forgotten Joint Score", "v": "Coorte prospettica a due gruppi: la media non differisce, ma la quota di chi sta peggio è minore con la non cementata; gruppi diversi all'origine (più giovani, più uomini). Numeri e incertezza nell'abstract.", "pmid": "42853330", "doi": "10.1007/s00402-026-06531-w", "temi": ["protesi totale di ginocchio", "cementazione", "Forgotten Joint Score"]}, {"dot": "gray", "j": "Bone Jt Open", "h": "Revisione di TKA: consenso Delphi su una classificazione dei difetti ossei alla TC", "v": "Esperti internazionali concordano che la classificazione guidi pianificazione e scelta dell'impianto e che la TC migliori la valutazione; manca l'accordo su dove tracciare le zone anatomiche. Consenso fra esperti, non una classificazione validata.", "pmid": "42852545", "doi": "10.1302/2633-1462.710.BJO-2026-0188.R1", "temi": ["revisione protesica", "difetti ossei", "consenso"]}, {"dot": "gray", "j": "Bone Joint J", "h": "Prevenzione dell'infezione periprotesica: aggiornamento a dieci anni delle raccomandazioni", "v": "Annotation non sistematica di Ferrini, Parvizi e altri che riassume le strategie perioperatorie, con prove di alta qualità ancora scarse in molti ambiti. L'abstract non riporta dati.", "pmid": "42853096", "doi": "10.1302/0301-620X.108B10.BJJ-2025-1731.R1", "temi": ["infezione periprotesica", "prevenzione", "linee guida"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Paura e recupero dopo protesi d'anca e ginocchio: un modello in quattro domini", "v": "Revisione sistematica: cinesiofobia e catastrofizzazione del dolore si associano a esiti peggiori; il modello FEAR è una proposta concettuale, non validata.", "pmid": "42855016", "doi": "10.1016/j.arth.2026.10.003", "temi": ["protesi", "paura del movimento", "recupero"]}, {"dot": "gray", "j": "SICOT-J", "h": "Da UKA a TKA con robot imageless CORI: tecnica passo per passo", "v": "Descrizione di un caso di conversione per allentamento asettico senza steli né augmenti; fattibile in quel caso, nessun confronto.", "pmid": "42852804", "doi": "10.1051/sicotj/2026045", "temi": ["UKA", "conversione in TKA", "chirurgia robotica"]}, {"dot": "gray", "j": "J Orthop Case Rep", "h": "Avulsione tibiale del LCP: fissazione artroscopica con un tunnel e sutura", "v": "Serie prospettica senza controllo con punteggi in rialzo e consolidazione radiografica; nessuna misura strumentale di lassità posteriore. Le date dello studio dichiarate (maggio-luglio 2026) non sembrano compatibili con il follow-up a sei mesi: da leggere con cautela.", "pmid": "42851620", "doi": "10.13107/jocr.2026.v16.i10.8302", "temi": ["LCP", "avulsione tibiale", "fissazione artroscopica"]}, {"dot": "gray", "j": "J Orthop Case Rep", "h": "Restrizione del flusso dopo LCA: serie prospettica senza gruppo di controllo", "v": "La sezione del quadricipite alla RM non cala in modo significativo e i punteggi migliorano, ma senza controllo nulla si può attribuire alla terapia.", "pmid": "42851926", "doi": "10.13107/jocr.2026.v16.i10.8322", "temi": ["LCA", "riabilitazione", "restrizione del flusso"]}, {"dot": "gray", "j": "J Athl Train", "h": "Dolore femororotuleo: l'arco di movimento intermedio fa più male", "v": "Studio trasversale in una sola seduta: dolore maggiore nell'arco intermedio e forza minore vicino all'estensione completa; indica dove l'esercizio è più tollerato, non se curi.", "pmid": "42852459", "doi": "10.4085/1062-6050-0046.26", "temi": ["dolore femororotuleo", "quadricipite", "esercizio"]}];
var SCOPERTE=[{"t": "L'IA nella biomeccanica dell'artrosi: la misura, la previsione e la decisione non sono la stessa cosa", "v": "Revisione narrativa (Frontiers in Bioengineering) che distingue l'IA che misura, quella che prevede nel tempo e quella che aiuta a decidere, separandole dalle tecnologie digitali che non sono IA. Vale la deviazione perché mette ordine in una letteratura in cui «IA» indica cose molto diverse; non porta dati propri.", "pmid": "42851913", "doi": "10.3389/fbioe.2026.1937199", "temi": ["intelligenza artificiale", "biomeccanica", "artrosi"]}, {"t": "Perché l'articolazione della mandibola si consuma prima del ginocchio", "v": "Studio sul topo, non sull'uomo: la cartilagine del condilo mandibolare ha un modulo elastico più basso e perde più in fretta le cellule progenitrici di superficie rispetto alla cartilagine tibiale. Vale la deviazione perché confronta due cartilagini con destini diversi; dato preclinico, nessuna ricaduta clinica diretta.", "pmid": "42852536", "doi": "10.1242/dmm.052994", "temi": ["cartilagine", "biologia", "artrosi"]}, {"t": "Un anno di biomeccanica dell'artrosi in quattro temi", "v": "Revisione sistematica annuale (Osteoarthritis and Cartilage, 176 studi da aprile 2025 ad aprile 2026): movimento e progressione, strumenti di misura fuori dal laboratorio, fenotipi di movimento e carichi individualizzati. Vale la deviazione per la mappa del campo; la maggior parte degli studi è trasversale.", "pmid": "42854819", "doi": "10.1016/j.joca.2026.10.003", "temi": ["biomeccanica", "artrosi", "revisione annuale"]}];
var SOC={"1": {"video": "Dopo la ricostruzione del legamento crociato con il tendine del quadricipite, quanto conta recuperare la forza presto? La Mayo Clinic ha seguito 100 pazienti: a 9 mesi la forza del muscolo operato era tra il 77 e l'81% dell'altra gamba. Eppure, a circa 2 anni, i punteggi riferiti dai pazienti erano buoni.\n\nChi aveva recuperato più forza già a 3 mesi tendeva ad avere un risultato migliore a 2 anni, e chi raggiungeva un livello di sintomi accettabile aveva in genere una forza del 60-70% già a 3 mesi. Quindi un indice di forza del 90% non sembra essere l'unica via per un buon risultato.\n\nIl limite: è un solo centro, senza gruppo di confronto, e mostra associazioni, non cause. Guarda i punteggi, non le nuove rotture.\nFonte: PubMed, PMID 42852663.", "linkedin": "Tendine quadricipitale nel LCA: LSI del quadricipite 77-81% a 9 mesi, Lysholm 90,7 e IKDC 77,8 a circa 2 anni (Kang, Krych e coll., Am J Sports Med, ottobre 2026).\n\n100 ricostruzioni con tendine quadricipitale; l'LSI isometrico del quadricipite a 3 mesi è associato all'IKDC a 2 anni (β=3,9; R² aggiustato 0,36; p<0,03); chi raggiunge la PASS ha in genere un LSI di 60-70% a 3 mesi.\n\nLimiti: serie monocentrica senza confronto, coefficienti senza intervalli di confidenza, associazioni e non cause, punteggi e non rotture.\nFonte: PubMed, PMID 42852663.", "instagram": "La forza dopo il crociato si recupera presto o tardi?\nIn uno studio su 100 persone la forza del muscolo operato era al 77-81% a 9 mesi, eppure i punteggi a 2 anni erano buoni.\nÈ uno studio di un solo centro, senza gruppo di confronto.\nFonte: PubMed, PMID 42852663.", "pazienti": "Dopo l'operazione al legamento crociato con un tratto del tendine del quadricipite, la forza del muscolo operato torna a poco a poco.\n\nIn uno studio su 100 persone, a 9 mesi era tra il 77% e l'81% di quella dell'altra gamba, ma a circa 2 anni i punteggi di funzione erano buoni. Chi aveva recuperato più forza già dopo 3 mesi tendeva ad avere un risultato migliore.\n\nLo studio è di un solo centro e non confronta altri metodi: il percorso si decide con il chirurgo e il fisioterapista.\nFonte: PubMed, PMID 42852663."}};
var SOCV={"1": {"video": {"chir": ["Tendine quadricipitale nel LCA: l'LSI del quadricipite a 9 mesi è 77-81%, e i flessori 98-100%. Serie della Mayo Clinic, Kang e Krych, Am J Sports Med, ottobre 2026.", "100 pazienti. A circa 2 anni Lysholm 90,7 e IKDC 77,8. L'LSI isometrico del quadricipite a 3 mesi è associato all'IKDC a 2 anni: beta 3,9, R quadro aggiustato 0,36. Chi raggiunge la PASS ha in genere un LSI del 60-70% a 3 mesi.", "Il limite: serie monocentrica senza confronto, nessun intervallo di confidenza nell'abstract, punteggi e non rotture dell'innesto. Una soglia del 90% non è raggiunta in media, ma l'esito è buono.\nFonte: PubMed, PMID 42852663."], "misto": ["Dopo il crociato con il tendine del quadricipite, a 9 mesi la forza del muscolo operato era tra il 77 e l'81% dell'altra gamba. È un dato della Mayo Clinic su 100 pazienti.", "Eppure a circa 2 anni i punteggi riferiti dai pazienti erano buoni. Chi aveva recuperato più forza già a 3 mesi tendeva ad avere un risultato migliore; chi raggiungeva un livello di sintomi accettabile aveva in genere il 60-70% a 3 mesi.", "Il limite: un solo centro, nessun gruppo di confronto, associazioni e non cause, e guarda i punteggi, non le nuove rotture.\nFonte: PubMed, PMID 42852663."], "pazienti": ["Dopo l'operazione al legamento crociato con un tratto del tendine del quadricipite, la forza del muscolo torna a poco a poco.", "In uno studio su 100 persone, a 9 mesi era tra il 77% e l'81% di quella dell'altra gamba, ma a circa 2 anni i punteggi erano buoni. Chi aveva recuperato più forza dopo 3 mesi tendeva ad andare meglio.", "Lo studio è di un solo centro e non confronta altri metodi: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42852663."]}, "linkedin": {"chir": ["LCA con tendine quadricipitale: LSI del quadricipite 77-81% a 9 mesi, flessori 98-100% (Kang, Krych e coll., Am J Sports Med, ottobre 2026), 100 ginocchia.", "A circa 2 anni Lysholm 90,7 e IKDC 77,8; LSI isometrico a 3 mesi su IKDC β=3,9, R² aggiustato 0,36 (p<0,03); PASS associata a un LSI di 60-70% a 3 mesi.", "Limiti: serie monocentrica senza confronto, nessun IC per i coefficienti, punteggi e non rotture, procedure associate non riportate.\nFonte: PubMed, PMID 42852663."], "misto": ["Crociato con tendine del quadricipite: a 9 mesi la forza del muscolo operato era al 77-81% dell'altra gamba (Mayo Clinic, 100 pazienti, ottobre 2026).", "A circa 2 anni i punteggi erano buoni; chi aveva più forza già a 3 mesi tendeva ad avere un risultato migliore.", "Limiti: un solo centro, nessun confronto, associazioni e non cause.\nFonte: PubMed, PMID 42852663."], "pazienti": ["Dopo il crociato con il tendine del quadricipite: in uno studio su 100 persone la forza era al 77-81% a 9 mesi.", "I punteggi a 2 anni erano buoni, e chi aveva recuperato più forza presto tendeva ad andare meglio.", "Studio di un solo centro, senza confronto: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42852663."]}, "instagram": {"chir": ["QT-ACLR: LSI e PROM.", "100 ginocchia: LSI quadricipite 77-81% a 9 mesi, IKDC 77,8 a 2 anni; LSI a 3 mesi β=3,9 sull'IKDC.", "Serie monocentrica, nessun IC.\nFonte: PubMed, PMID 42852663."], "misto": ["La forza dopo il crociato torna a poco a poco.", "In 100 persone era al 77-81% a 9 mesi, ma i punteggi a 2 anni erano buoni.", "Un solo centro, nessun confronto.\nFonte: PubMed, PMID 42852663."], "pazienti": ["La forza dopo il crociato torna a poco a poco.", "In 100 persone era tra il 77% e l'81% a 9 mesi, ma i punteggi a 2 anni erano buoni.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42852663."]}, "reel": {"chir": ["LCA con tendine quadricipitale.", "LSI a 9 mesi 77-81%, IKDC 77,8 a 2 anni.", "Serie monocentrica, nessun IC."], "misto": ["Forza dopo il crociato.", "Al 77-81% a 9 mesi, punteggi buoni a 2 anni.", "Un solo centro."], "pazienti": ["Forza dopo il crociato.", "Torna a poco a poco, punteggi buoni a 2 anni.", "Studio piccolo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #legamentocrociato #tendinequadricipitale #riabilitazione #forzamuscolare #chirurgiaartroscopica #chirurgiaortopedica #ortopediaticino #medicinabasatasulleprove", "kw": "legamento crociato anteriore, tendine quadricipitale, forza muscolare dopo il crociato, riabilitazione"}};
var NLB={"1": {"prof": ["Tendine quadricipitale: la forza a 3 mesi predice l'IKDC a 2 anni", "Serie della Mayo Clinic (Am J Sports Med, ottobre 2026) su 100 ricostruzioni del LCA con tendine quadricipitale: a 9 mesi l'LSI del quadricipite è 77-81% e quello dei flessori 98-100%; a circa 2 anni Lysholm 90,7 e IKDC 77,8. L'LSI isometrico del quadricipite a 3 mesi è associato all'IKDC a 2 anni (β=3,9; R² aggiustato 0,36; p<0,03) e chi raggiunge la PASS ha in genere un LSI di 60-70% a 3 mesi.", "Nota critica: serie monocentrica senza confronto, coefficienti senza intervalli di confidenza, associazioni e non cause; punteggi a 2 anni, non rotture; tecnica di prelievo e procedure associate non riportate nell'abstract."], "mix": ["Crociato con tendine del quadricipite: la forza dei primi mesi si lega al risultato a 2 anni", "In 100 persone operate al legamento crociato con un tratto del tendine del quadricipite, la forza del muscolo operato rispetto all'altra gamba era del 77-81% a 9 mesi, mentre quella dei muscoli posteriori della coscia era quasi pari (98-100%). A circa 2 anni i punteggi riferiti dai pazienti erano buoni (Lysholm 90,7, IKDC 77,8). Chi aveva recuperato più forza già a 3 mesi tendeva ad avere un punteggio più alto a 2 anni.", "Nota sul limite: è un solo centro, senza gruppo di confronto, e mostra associazioni, non cause; guarda i punteggi a 2 anni e non le nuove rotture, e nel riassunto non è riportata la tecnica con cui è stato prelevato il tendine."], "paz": ["Dopo l'operazione al crociato, recuperare forza presto si associa a un risultato migliore", "Dopo la ricostruzione del legamento crociato con un tratto del tendine del quadricipite, in uno studio su 100 persone chi aveva recuperato più forza nel muscolo già dopo 3 mesi tendeva ad avere un punteggio migliore a 2 anni. A 9 mesi la forza della gamba operata era in media tra il 77% e l'81% di quella dell'altra gamba.", "È uno studio di un solo centro, senza gruppo di confronto: mostra un legame, non dimostra una causa. Il percorso di riabilitazione si decide con il chirurgo e il fisioterapista."], "kw": "legamento crociato anteriore, tendine quadricipitale, forza muscolare, riabilitazione"}, "2": {"prof": ["LET con il LCA nei giovani: la cinematica del passo a 4 mesi non cambia", "Coorte retrospettiva di Montréal (Am J Sports Med, ottobre 2026) su 70 pazienti ≤18 anni, 35 LCA con LET e 35 LCA isolato: a circa 4 mesi nessuna differenza significativa della cinematica 3D del passo in alcun piano (tutti p>0,05); rotazione tibiale media 1,03° ± 4,27° contro 1,61° ± 3,51°.", "Nota critica: 4 mesi sono pochi per il timore di sovravincolo e artrosi, il passo in piano non mette alla prova il pivoting, il confronto non è randomizzato, innesto e tecnica del LET non sono riportati; «nessuna differenza» con questi gruppi non è equivalenza."], "mix": ["Tenodesi laterale aggiunta al crociato nei ragazzi: il modo di camminare dopo 4 mesi è simile", "In 70 ragazzi operati al legamento crociato, metà con un rinforzo laterale esterno all'articolazione (tenodesi) e metà senza, i movimenti del ginocchio durante la camminata a circa 4 mesi non mostravano differenze rilevanti. Gli autori ne concludono che a questo stadio il rinforzo non sembra irrigidire il ginocchio.", "Nota sul limite: quattro mesi sono presto per sapere che cosa succede negli anni, la camminata è un gesto poco impegnativo e i due gruppi non erano stati assegnati a caso; non è riportato quale tendine sia stato usato."], "paz": ["Un rinforzo laterale al crociato nei ragazzi non cambia il modo di camminare dopo 4 mesi", "In uno studio su 70 ragazzi operati al legamento crociato, quelli che hanno avuto anche un piccolo rinforzo laterale del ginocchio camminavano, dopo circa 4 mesi, come quelli che non l'hanno avuto.", "Lo studio guarda solo i primi mesi e non dice se il rinforzo riduca le nuove rotture: se ne parla con il chirurgo, caso per caso."], "kw": "tenodesi laterale, legamento crociato, ragazzi, camminata"}, "3": {"prof": ["LCA più ALL: controllo posturale dinamico migliore a 3 mesi che con LCA isolato", "Studio coreano (Clin Biomech, ottobre 2026) su 67 pazienti, 37 con LCA isolato e 30 con LCA più ALL: al Y-balance le direzioni postero-mediale (p=0,009) e postero-laterale (p=0,049) sono migliori con la ricostruzione combinata; per gli autori il vantaggio è a 3 mesi.", "Nota critica: gruppi non randomizzati, p=0,049 al limite senza correzione per confronti multipli dichiarata, dimensioni dell'effetto e intervalli di confidenza non riportati, nessun esito duro; la tecnica dell'ALL e l'innesto non sono riportati."], "mix": ["Crociato più legamento antero-laterale: equilibrio in movimento migliore dopo 3 mesi", "In 67 persone operate al legamento crociato, 30 con la ricostruzione anche del legamento antero-laterale (che aiuta a controllare la rotazione) e 37 senza, il test di equilibrio in movimento (Y-balance) risultava migliore con la ricostruzione combinata in due direzioni, quelle legate alla stabilità in rotazione.", "Nota sul limite: i gruppi non erano formati a caso, una delle differenze è al limite della significatività statistica e il riassunto non dice di quanto sia migliore l'equilibrio; non misura le nuove rotture."], "paz": ["Il legamento antero-laterale aggiunto al crociato: un test di equilibrio migliore dopo 3 mesi", "In uno studio su 67 persone operate al legamento crociato, chi aveva avuto anche la ricostruzione di un legamento laterale del ginocchio faceva meglio, dopo 3 mesi, un test di equilibrio durante il movimento.", "Lo studio è piccolo e non dice se questo si traduca in meno nuovi infortuni: se ne parla con il chirurgo."], "kw": "legamento antero-laterale, legamento crociato, equilibrio, riabilitazione"}, "4": {"prof": ["MPFL negli adolescenti: ACL-RSI ≥59,2 associato al rientro allo sport", "Coorte retrospettiva monocentrica (Am J Sports Med, ottobre 2026) su 97 adolescenti operati di MPFL con o senza osteotomia della tuberosità tibiale: rientro allo sport nel 78,3%; ACL-RSI ≥59,2 con AUC 0,70 (IC 95% 0,56-0,83); OR 3,56 aggiustato per sesso (IC 95% 1,10-11,51; p=0,033).", "Nota critica: soglia ricavata e valutata sullo stesso campione, AUC con limite inferiore 0,56, OR molto impreciso, ACL-RSI nato per il LCA, tecnica del MPFL non riportata; non è un criterio di rientro validato."], "mix": ["Dopo l'intervento alla rotula negli adolescenti, la fiducia si lega al rientro allo sport", "In 97 adolescenti operati per instabilità della rotula (ricostruzione del legamento che la trattiene), tre su quattro sono tornati allo sport. Un questionario sulla fiducia psicologica a tornare (ACL-RSI) con punteggio pari o superiore a 59,2 si associava a una probabilità maggiore di rientro.", "Nota sul limite: la soglia è stata trovata e verificata sugli stessi ragazzi, il questionario era nato per il crociato e il risultato è impreciso; non è un punteggio da usare da solo per decidere il rientro."], "paz": ["Dopo un'operazione alla rotula, la fiducia nel ginocchio conta per tornare allo sport", "In uno studio su 97 adolescenti operati per instabilità della rotula, chi si sentiva più sicuro di poter tornare, secondo un questionario, aveva più probabilità di tornare davvero allo sport.", "Lo studio è di un solo centro e il questionario non è nato per questo problema: il rientro si decide con il chirurgo e il fisioterapista."], "kw": "instabilità della rotula, legamento patello-femorale mediale, adolescenti, rientro allo sport"}, "5": {"prof": ["Lesioni ramp nel LCA: 28,0% di incidenza, risonanza sensibile al 57,1%", "Studio prospettico indiano (J Orthop Case Rep, ottobre 2026) su 50 ricostruzioni del LCA: lesione ramp in 14 (28,0%; IC 95% di Wilson 17,5-41,7%, calcolo mio); la risonanza ne vede 8 su 14 (57,1%), l'ispezione artroscopica sistematica del compartimento postero-mediale le trova tutte. Nelle ramp pivot-shift positivo nell'85,7% e Lachman III nel 78,6%.", "Nota critica: l'artroscopia è il riferimento per definizione, quindi la ricerca sistematica non ha sensibilità misurabile; sensibilità della risonanza con IC 32,6-78,6% (calcolo mio); un centro, 6 mesi, trattamento delle ramp non riportato."], "mix": ["Crociato e lesioni ramp del menisco: la risonanza ne perde circa la metà", "In 50 persone operate al legamento crociato, 14 avevano una lesione ramp (un distacco della parte posteriore del menisco interno, 28%). La risonanza ne aveva riconosciute 8 su 14; guardando con l'artroscopio nella parte posteriore del ginocchio sono state viste tutte. Chi aveva una lesione ramp tendeva ad avere un ginocchio più instabile prima dell'operazione.", "Nota sul limite: lo studio è piccolo, di un solo centro e dura 6 mesi; il numero di casi con ramp è 14, quindi le percentuali sono molto imprecise, e il riassunto non dice come le lesioni siano state trattate."], "paz": ["Una lesione del menisco interno spesso non si vede alla risonanza, ma durante l'intervento", "In uno studio su 50 persone operate al legamento crociato, circa una su quattro aveva una lesione nella parte posteriore del menisco interno (lesione ramp). La risonanza ne aveva mostrate poco più della metà; durante l'operazione, guardando con l'artroscopio, sono state trovate tutte.", "Lo studio è piccolo e di un solo centro: se ne parla con il chirurgo, che decide caso per caso."], "kw": "lesione ramp, menisco, legamento crociato, artroscopia"}, "6": {"prof": ["TKA robotica: due classi CPAK di differenza si associano a un OKS inferiore a 3 e 6 mesi", "Coorte retrospettiva multicentrica (Bone Joint J, ottobre 2026) su 297 TKA robotiche: 6,4% (19) si sposta di due fenotipi CPAK, con miglioramento dell'OKS minore a 3 mesi (p=0,008) e a 6 mesi (p=0,036); LDFA oltre 4° dal nativo: miglioramento mediano più basso (7,14, DS 9,9 a 3 mesi).", "Nota critica: sottogruppo di 19 pazienti, analisi esplorativa dichiarata, nessun dato a 12 mesi, nessun IC né correzione per confondenti nell'abstract; piattaforma robotica e target di allineamento non riportati."], "mix": ["Protesi robotica: cambiare molto l'allineamento naturale si associa a un recupero più lento", "In 297 persone con protesi totale di ginocchio posizionata con il robot, circa una su sedici (19) ha avuto un allineamento finale molto diverso da quello di partenza. In queste persone il miglioramento del punteggio del ginocchio (Oxford Knee Score) a 3 e 6 mesi è stato minore che negli altri.", "Nota sul limite: sono pochi pazienti, l'analisi è definita dagli autori esplorativa e non sono riportati i dati a un anno né quali altri fattori possano spiegare la differenza."], "paz": ["Protesi di ginocchio con il robot: il recupero iniziale può dipendere dall'allineamento", "In uno studio su 297 persone con protesi di ginocchio posizionata con il robot, un piccolo gruppo di 19 ha avuto un cambiamento marcato della forma dell'allineamento rispetto a prima, e nei primi 6 mesi ha migliorato meno degli altri.", "Sono pochi casi e l'analisi è esplorativa: non dice che cosa fare, e il tipo di protesi si discute con il chirurgo."], "kw": "protesi di ginocchio, chirurgia robotica, allineamento, recupero"}, "7": {"prof": ["TKA non cementata: polietilene reticolato senza progressione dell'usura a 10 anni (RCT)", "RCT in doppio cieco (Bone Joint J, ottobre 2026) su 96 TKA non cementate con radiostereometria a 10 anni: usura mediale del polietilene reticolato 0,15 → 0,13 mm da 5 a 10 anni, convenzionale 0,22 → 0,46 mm; migrazione tibiale 0,99 mm (IC 95% 0,83-1,18) contro 1,05 mm (0,87-1,24).", "Nota critica: differenza di usura senza IC né p nell'abstract, un solo impianto e un solo centro, esiti surrogati (usura e migrazione, non revisioni), perdite al follow-up non riportate."], "mix": ["Protesi di ginocchio non cementata: a 10 anni il polietilene più resistente si consuma meno", "In uno studio a 10 anni su 96 protesi di ginocchio non cementate, assegnate a caso e in doppio cieco, l'inserto in polietilene più resistente (reticolato) smetteva di consumarsi dopo il quinto anno, mentre quello tradizionale continuava (0,46 contro 0,13 mm a 10 anni). I componenti non si erano spostati in modo diverso nei due gruppi e i punteggi dei pazienti erano simili.", "Nota sul limite: è uno studio su un solo modello di protesi, misura il consumo e lo spostamento e non quante protesi siano state rioperate; per la differenza di consumo il riassunto non riporta l'intervallo di confidenza."], "paz": ["Protesi di ginocchio: l'inserto in polietilene più resistente si consuma meno dopo 10 anni", "In uno studio durato 10 anni su 96 protesi di ginocchio, l'inserto in plastica più resistente si è consumato meno di quello tradizionale, e le protesi non cementate sono rimaste stabili nei due gruppi.", "Lo studio riguarda un solo modello di protesi: la scelta si discute con il chirurgo."], "kw": "protesi totale di ginocchio, polietilene, usura, 10 anni"}, "8": {"prof": ["Incisura e pendenza tibiale: nessuna differenza rilevabile fra Asia e Occidente", "Revisione sistematica con meta-analisi (J ISAKOS, ottobre 2026) di 31 studi RM, 2.463 ginocchia con LCA integro: larghezza dell'incisura 20,13 contro 19,86 mm (p=0,77), pendenza mediale 5,66° contro 6,04° (p=0,67) e laterale 5,73° contro 6,24° (p=0,53), larghezza del LCA 5,20 contro 7,62 mm (p=0,08); I² 75-100%.", "Nota critica: eterogeneità elevata e intervalli di predizione ampi, quindi assenza di differenza rilevabile e non equivalenza (come dicono gli autori); coorti definite per paese e non per etnia; nessun esito di rottura."], "mix": ["Forma del ginocchio e crociato: nessuna differenza rilevabile fra Asia e Occidente", "Mettendo insieme 31 studi di risonanza (2.463 ginocchia), le misure dello spazio in cui passa il legamento crociato e dell'inclinazione della parte alta della tibia non risultavano diverse in modo significativo fra le popolazioni asiatiche e quelle occidentali.", "Nota sul limite: gli studi erano molto diversi fra loro, quindi «nessuna differenza rilevabile» non vuol dire che le popolazioni siano uguali; le popolazioni sono definite dal paese e la revisione non misura il rischio di rottura."], "paz": ["Il ginocchio è simile in Asia e in Occidente? Nessuna differenza netta in una revisione", "Una revisione di 31 studi di risonanza ha confrontato alcune misure del ginocchio legate al rischio di rottura del legamento crociato fra popolazioni asiatiche e occidentali, senza trovare differenze nette.", "Gli studi sono molto diversi fra loro: il risultato non dice che le popolazioni siano identiche e non vale per una singola persona."], "kw": "anatomia del ginocchio, legamento crociato, risonanza magnetica, pendenza tibiale"}, "9": {"prof": ["OATS nei difetti ICRS IV di 2-4 cm²: Lysholm 93,03 e IKDC 91,24 a 18 mesi", "Coorte prospettica indiana (J Orthop Case Rep, ottobre 2026) su 38 pazienti di 15-40 anni, 35 seguiti a 18 mesi: Lysholm 50,29 ± 10,90 → 93,03 ± 4,11, IKDC 48,29 ± 9,45 → 91,24 ± 4,55 (p<0,001); RM con superficie congruente nel 91,4% e cistica o delaminazione nell'8,6%.", "Nota critica: braccio singolo senza confronto con AMIC, microfratture o condrociti, 18 mesi di follow-up, un centro, Tegner finale 8,71 non discusso, 3 pazienti persi su 38."], "mix": ["Trapianto di cartilagine con osso del paziente stesso: buoni risultati a 18 mesi nei giovani", "In 38 giovani con una lesione profonda della cartilagine e dell'osso del ginocchio, trattata spostando un cilindro di cartilagine e osso da una zona meno sollecitata, i punteggi di funzione sono saliti molto a 18 mesi e alla risonanza l'innesto era ben integrato in tutti i casi seguiti. Nessun innesto è fallito e nessuno ha avuto problemi nel punto di prelievo.", "Nota sul limite: non c'è un gruppo di confronto, il controllo dura 18 mesi, è un solo centro e 3 persone su 38 non sono state seguite fino alla fine; non si può dire se altri metodi darebbero risultati simili."], "paz": ["Cartilagine del ginocchio nei giovani: buoni risultati a 18 mesi con un trapianto dal paziente", "In uno studio su 38 giovani con una lesione della cartilagine e dell'osso del ginocchio, un trapianto di cartilagine e osso prelevati dal ginocchio stesso ha portato a un netto miglioramento della funzione dopo 18 mesi.", "Lo studio non confronta altri metodi e dura poco: il tipo di trattamento si sceglie con il chirurgo, caso per caso."], "kw": "cartilagine del ginocchio, trapianto osteocondrale, lesione della cartilagine, giovani"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Am J Sports Med",h:"Innesto quadricipitale: la forza a 3 mesi predice l'IKDC a 2 anni",v:"Serie di 100 ricostruzioni del LCA con tendine quadricipitale (Mayo Clinic): a 9 mesi l'LSI del quadricipite è 77-81% (flessori 98-100%), eppure a circa 2 anni Lysholm 90,7 e IKDC 77,8. L'LSI isometrico del quadricipite a 3 mesi è associato all'IKDC a 2 anni (β=3,9; R² aggiustato 0,36; p<0,03); chi raggiunge la soglia PASS ha in genere un LSI di 60-70% già a 3 mesi. Intervalli di confidenza dei coefficienti non riportati nell'abstract.",ax:"Kang, Ina, Johnson, Iyer, Duchman, Hevesi, Camp, Saris, Krych, Tagliero",date:"ott 2026",meta:"serie di casi, 100 ginocchia, tendine quadricipitale, LSI a 3-6-9 mesi · [IV per livello dichiarato]",pmid:'42852663',doi:'10.1177/03635465261490238',journal:"The American journal of sports medicine",authors:"Kang LS, Ina JG, Johnson A, Iyer S, Duchman KR, Hevesi M, Camp CL, Saris DBF, Krych AJ, Tagliero AJ",design:"Serie di casi della Mayo Clinic (Rochester, Minnesota), livello di evidenza 4 dichiarato: ricostruzioni primarie del LCA con autoinnesto di tendine quadricipitale fra il 2021 e il 2024, con test LSI durante la riabilitazione (forza isometrica e isocinetica, Y-Balance, salti) a 3, 6 e 9 mesi e questionari a circa 2 anni; inclusi solo pazienti senza revisione né ulteriori interventi al ginocchio. Regressione lineare multivariata aggiustata per età, sesso e BMI; curve ROC per le soglie PASS. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"100 ginocchia in 100 pazienti; età media 25,3 ± 11,2 anni; BMI 25,9 ± 6,5 kg/m²; 52% uomini. Follow-up medio 2,0 ± 0,7 anni. Tecnica e sede di prelievo del tendine, riabilitazione, sport praticato e procedure associate (LET, menisco) non riportati nell'abstract.",results:"LSI a 9 mesi: forza del quadricipite 77-81%, flessori 98-100%. A circa 2 anni: soddisfazione 8,4 su 10, Lysholm 90,7, IKDC 77,8. Regressione aggiustata per età, sesso e BMI: LSI isometrico del quadricipite a 3 mesi su IKDC β=3,9 (R² aggiustato 0,36; p<0,03); a 6 mesi LSI isocinetico di quadricipite e flessori su IKDC β=2,9-3,7 (R² aggiustato 0,13-0,17; p<0,05); a 9 mesi il quadricipite «fast» su Lysholm e IKDC β=3,9-4,7 (R² aggiustato 0,34-0,35; p≤0,003). Lysholm e IKDC discriminano la soddisfazione con AUC 0,927-0,937 (p<0,001); chi raggiunge la PASS dell'IKDC ha in genere un LSI di 60-70% a 3 mesi. Intervalli di confidenza dei coefficienti e unità di β non riportati nell'abstract.",concl:"Gli autori: dopo ricostruzione con tendine quadricipitale gli LSI di forza sono associati in modo indipendente ai punteggi a 2 anni; la forza isometrica del quadricipite a 3 mesi predice un IKDC più alto e quella isocinetica a 9 mesi predice sia IKDC sia Lysholm; ne ricavano il valore del recupero precoce del quadricipite e degli LSI per orientare la riabilitazione.",limits:"Serie monocentrica senza gruppo di confronto: non si sa se con altri innesti la relazione cambi · associazioni, non cause; R² fra 0,13 e 0,36, cioè gran parte della variabilità dei punteggi resta non spiegata · punteggi a 2 anni, non rotture dell'innesto né rientro allo sport · medie di LSI, non la distribuzione dei pazienti sotto il 90% · procedure associate (LET, menisco) e tecnica di prelievo non riportate · testo completo non disponibile.",perte:"Il tendine quadricipitale è l'innesto più vicino al tuo (retto femorale / tendine quadricipitale superficiale), ma non è lo stesso prelievo, e l'abstract non dice se c'era il LET: trasferibilità parziale. Per T4 il dato è doppio: a 9 mesi la media dell'LSI del quadricipite è 77-81%, sotto qualunque soglia del 90%, eppure i punteggi a 2 anni sono buoni; e chi arriva alla PASS ha già a 3 mesi un LSI di 60-70%. Mette in discussione l'LSI ≥90% come cancello unico di rientro, senza proporne uno nuovo: è una media, non dice quanti pazienti sotto il 90% abbiano comunque un esito scarso."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"LET nel LCA dei giovani: a 4 mesi il passo non cambia",v:"Coorte retrospettiva di 70 pazienti ≤18 anni (35 LCA con LET, 35 LCA isolato; età media 15,8 ± 1,3 anni): a circa 4 mesi nessuna differenza significativa della cinematica 3D del passo in alcun piano (tutti p>0,05); rotazione tibiale media 1,03° ± 4,27° contro 1,61° ± 3,51°. Intervalli di confidenza non riportati nell'abstract.",ax:"Manitiu, Mazy, Bayol, Blouin, Saunders, Hagemeister, Nault",date:"ott 2026",meta:"coorte retrospettiva, 70 pazienti (35 contro 35), analisi 3D del passo a circa 4 mesi · [III]",pmid:'42852835',doi:'10.1177/03635465261487281',journal:"The American journal of sports medicine",authors:"Manitiu A, Mazy D, Bayol A, Blouin V, Saunders P, Hagemeister N, Nault ML",design:"Coorte retrospettiva (livello di evidenza 3 dichiarato) di Montréal (Université de Montréal, CHU Sainte-Justine): pazienti pediatrici operati di LCA con o senza LET fra gennaio 2023 e gennaio 2026, tutti con analisi standardizzata del passo con cinesiografia del ginocchio prima e dopo l'intervento. Esito primario: forme d'onda cinematiche 3D nei tre piani, analizzate con mappatura statistica parametrica monodimensionale. Testo completo non aperto: contenuto dall'abstract.",pop:"70 pazienti (70 ginocchia), età media 15,8 ± 1,3 anni; 35 LCA isolato e 35 LCA con LET. Tipo di innesto, tecnica del LET e riabilitazione non riportati nell'abstract. Follow-up: circa 4 mesi (123,3 ± 58,4 giorni).",results:"Prima dell'intervento una differenza piccola ma significativa della rotazione tibiale (1,8°) fra il 34-38% e il 57-59% del ciclo del passo (p=0,032 e p=0,034). A circa 4 mesi nessuna differenza significativa della cinematica del ginocchio in alcun piano (tutti p>0,05). Rotazione tibiale postoperatoria media 1,03° ± 4,27° (LCA isolato) contro 1,61° ± 3,51° (LCA con LET). Intervallo di confidenza della differenza non riportato nell'abstract.",concl:"Gli autori: l'aggiunta del LET non modifica in modo significativo la biomeccanica 3D del passo a circa 4 mesi, a sostegno della sicurezza del LET come complemento al LCA nei pazienti giovani; servono studi longitudinali con test funzionali più impegnativi per confermarlo oltre la fase precoce.",limits:"Quattro mesi: il timore di sovravincolo laterale e di artrosi riguarda anni, non mesi · il passo in piano è un compito a bassa richiesta e non mette alla prova la rotazione nel pivoting · retrospettivo, gruppi non randomizzati, con una differenza già presente prima dell'intervento · tipo di innesto e tecnica del LET non riportati · nessun esito di rottura dell'innesto.",perte:"Tocca il tuo LET, che fai su tutti: è una domanda di sicurezza (non sovravincola la cinematica del passo) posta nella fascia dei più giovani, vicina ai tuoi 14 anni. Ma l'abstract non dice né l'innesto né la tecnica del LET, quindi non so se somigli al tuo Lemaire onlay; e a 4 mesi non si può escludere un effetto tardivo. Per T1 non cambia nulla: non dice nulla sul fallimento dell'innesto."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Clin Biomech",h:"LCA più ALL: equilibrio dinamico migliore a 3 mesi",v:"67 pazienti (37 LCA isolato, 30 LCA più ricostruzione del legamento antero-laterale) con Biodex e Y-balance prima e a 3 e 6 mesi: Y-balance postero-mediale (p=0,009) e postero-laterale (p=0,049) migliori nel gruppo con ALL; gli autori concludono per un controllo dinamico migliore a 3 mesi. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Kim, Hwang, Baek, Chung",date:"ott 2026",meta:"studio comparativo, 67 pazienti (37 contro 30), Y-balance e Biodex a 3 e 6 mesi · [III per disegno]",pmid:'42854272',doi:'10.1016/j.clinbiomech.2026.106986',journal:"Clinical biomechanics (Bristol, Avon)",authors:"Kim JS, Hwang UJ, Baek SH, Chung KS",design:"Studio comparativo del Dipartimento di Fisioterapia dell'Ilsan Paik Hospital (Inje University, Corea del Sud, afferenza del primo autore): pazienti operati fra giugno 2016 e luglio 2022 di LCA isolato (37) o di LCA con ricostruzione del legamento antero-laterale (30); controllo posturale statico e dinamico con Biodex Balance System e Y-balance test prima e a 3 e 6 mesi dall'intervento. Il disegno non è dichiarato nell'abstract (il periodo 2016-2022 fa pensare a un'analisi retrospettiva: inferenza mia). Testo completo non aperto: contenuto dall'abstract.",pop:"67 pazienti (49 uomini, 18 donne), età media 30,2 ± 8,1 anni, BMI 25,98 ± 3,6 kg/m². Tipo di innesto, tecnica dell'ALL e riabilitazione non riportati nell'abstract. Follow-up: 3 e 6 mesi.",results:"Y-balance: effetti principali significativi di tempo e di gruppo in tutte le direzioni salvo l'anteriore. Direzione postero-mediale p=0,009 e postero-laterale p=0,049 migliori con LCA più ALL rispetto al LCA isolato. Gli autori concludono per un controllo posturale dinamico migliore a 3 mesi con la ricostruzione combinata. Valori medi, dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract; risultati del Biodex non riportati nell'abstract.",concl:"Gli autori: a 3 mesi la ricostruzione combinata LCA più ALL ha mostrato un controllo posturale dinamico migliore del LCA isolato, in particolare nei compiti con aggiustamenti posturali multidirezionali; le direzioni postero-mediale e postero-laterale riflettono la stabilità rotatoria del ginocchio.",limits:"Gruppi di 37 e 30 pazienti non randomizzati e probabilmente retrospettivi: chi riceve l'ALL può differire per lassità o per rotazione · p=0,049 è al limite, e non è dichiarata una correzione per confronti multipli (direzioni, tempi, strumenti) · il Y-balance è una misura indiretta, non misura la lassità rotatoria né la rottura · innesto, tecnica dell'ALL e riabilitazione non riportati · nessun esito clinico duro.",perte:"Parla del tuo problema, la stabilità rotatoria con il crociato, ma con una ricostruzione dell'ALL con innesto, non con il tuo Lemaire modificato onlay: costrutti diversi, quindi trasferibilità parziale; l'abstract non dice nemmeno l'innesto del LCA. È un dato funzionale a 3 mesi: non tocca la rottura dell'innesto (T1), semmai ricorda che accanto alla forza (T4) esistono test di controllo dinamico."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"Dopo MPFL negli adolescenti, l'ACL-RSI ≥59,2 si lega al rientro allo sport",v:"97 adolescenti (10-19 anni) operati di stabilizzazione rotulea (MPFL con o senza osteotomia della tuberosità tibiale): rientro allo sport nel 78,3% (76). Soglia ACL-RSI ≥59,2 con AUC 0,70 (IC 95% 0,56-0,83); in regressione multivariata aggiustata per sesso OR 3,56 (IC 95% 1,10-11,51; p=0,033).",ax:"Kim, Turlip, Thothadri, Redler, Greenberg, Williams",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 97 adolescenti, ACL-RSI · [III]",pmid:'42852817',doi:'10.1177/03635465261487282',journal:"The American journal of sports medicine",authors:"Kim CL, Turlip RW, Thothadri M, Redler LH, Greenberg E, Williams BA",design:"Coorte retrospettiva monocentrica (livello di evidenza 3 dichiarato; Perelman School of Medicine, University of Pennsylvania, afferenza del primo autore): adolescenti di 10-19 anni operati per instabilità rotulea con ricostruzione del MPFL con o senza osteotomia della tuberosità tibiale fra gennaio 2020 e ottobre 2024, attivi nello sport alla prima visita e con ACL-RSI compilato durante la riabilitazione. Soglia ottimale dell'ACL-RSI dalla distanza euclidea, accuratezza con curva ROC, regressione logistica multivariata aggiustata per sesso. Testo completo non aperto: contenuto dall'abstract.",pop:"97 pazienti, età mediana 15,6 anni (IQR 14,2-16,4): 70 MPFL isolato, 27 MPFL con osteotomia della tuberosità tibiale. Rientro allo sport 78,3% (n=76). Tecnica di ricostruzione del MPFL (innesto, fissazione), numero di lussazioni precedenti e follow-up non riportati nell'abstract.",results:"Il rientro allo sport è associato a ACL-RSI più alto (p=0,012), MPFL isolato (p=0,011) e sesso maschile (p=0,03). Soglia ACL-RSI ≥59,2: AUC 0,70 (IC 95% 0,56-0,83). Nella regressione multivariata aggiustata per sesso la soglia resta l'unico predittore significativo (OR 3,56; IC 95% 1,10-11,51; p=0,033); il tipo di intervento no.",concl:"Gli autori: un ACL-RSI ≥59,2 si associa a una maggiore probabilità di rientro allo sport dopo chirurgia di stabilizzazione rotulea negli adolescenti; dati demografici e caratteristiche della lesione studiati non sembrano influenzare il rientro.",limits:"Retrospettivo e monocentrico · la soglia 59,2 è ricavata e valutata sullo stesso campione, senza validazione esterna, e un'AUC 0,70 con limite inferiore 0,56 è vicina al caso · OR con IC da 1,10 a 11,51: stima molto imprecisa · l'ACL-RSI nasce per il LCA, non per l'instabilità rotulea · sono inclusi solo i pazienti che hanno compilato il questionario (selezione) · tecnica del MPFL, tempo di compilazione e follow-up non riportati.",perte:"Il MPFL è una tua ricostruzione (ancore FiberTak onlay), ma l'abstract non dice né l'innesto né la fissazione, e la fascia 10-19 anni scende sotto i tuoi 14. Il dato utile è psicologico: il questionario che già conosci per il LCA sembra dare un segnale anche dopo il MPFL; ma una soglia non validata fuori dal campione non è un criterio di rientro. Nessuna tensione si muove."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Case Rep",h:"Lesioni ramp nel LCA: la risonanza ne perde 6 su 14",v:"Studio prospettico su 50 pazienti operati di LCA: lesione ramp in 14 (28,0%; IC 95% di Wilson 17,5-41,7%, calcolo mio). La risonanza ne vede 8 su 14 (57,1%), l'ispezione artroscopica sistematica del compartimento postero-mediale le trova tutte. Nelle ramp pivot-shift positivo nell'85,7% e Lachman di grado III nel 78,6%; Lysholm 49,3 ± 8,6 → 90,6 ± 5,2 e IKDC 44,7 ± 7,8 → 85,8 ± 6,0 a 6 mesi.",ax:"Thomas, Nayak, Singh, Syal, Akram, Neeraj",date:"ott 2026",meta:"studio prospettico osservazionale, 50 pazienti, 6 mesi · [IV per disegno]",pmid:'42851631',doi:'10.13107/jocr.2026.v16.i10.8330',journal:"Journal of orthopaedic case reports",authors:"Thomas A, Nayak M, Singh SK, Syal A, Akram MA, Neeraj P",design:"Studio prospettico osservazionale (Sub District Hospital di Valsad, Gujarat, India, afferenza del primo autore): 50 pazienti con lesione del LCA operati in artroscopia; ricerca sistematica della lesione ramp (distacco menisco-capsulare o menisco-tibiale del corno posteriore del menisco mediale) nel compartimento postero-mediale, confronto con la risonanza preoperatoria, esiti con Lysholm e IKDC. Centro unico, senza gruppo di controllo. Testo completo su PMC non aperto: contenuto dall'abstract.",pop:"50 pazienti con lesione del LCA; età e sesso non riportati nell'abstract. Lesione ramp in 14 (28,0%). Follow-up: 6 mesi. Trattamento delle ramp (sutura o altro) non riportato nell'abstract.",results:"Incidenza delle ramp 28,0% (14 su 50; IC 95% di Wilson 17,5-41,7%, calcolo mio). Risonanza: 8 delle 14 (57,1%; IC 95% di Wilson 32,6-78,6%, calcolo mio), 6 mancate (42,9%); l'artroscopia le ha identificate tutte. Nelle ramp pivot-shift positivo nell'85,7% e Lachman di grado III nel 78,6%; i valori nei pazienti senza ramp e il p del confronto non sono nell'abstract. Lysholm da 49,3 ± 8,6 a 90,6 ± 5,2 e IKDC da 44,7 ± 7,8 a 85,8 ± 6,0 a 6 mesi (tutti i pazienti). Nessuna complicazione nell'86,0%; tipo delle altre non riportato.",concl:"Gli autori: le lesioni ramp sono frequenti nei ginocchi con LCA deficitario e spesso non diagnosticate alla risonanza; la valutazione artroscopica sistematica ne migliora l'individuazione, e l'identificazione e il trattamento precoci si accompagnano a un ottimo recupero funzionale.",limits:"50 pazienti, un centro, 6 mesi · l'artroscopia è il riferimento per definizione: che trovi tutte le ramp è circolare, mentre la sensibilità della risonanza (8 su 14) ha un intervallo largo, 32,6-78,6% · nessun gruppo senza ramp o con ramp non trattate nell'abstract: l'«ottimo recupero» non si attribuisce al trattamento della ramp · trattamento delle ramp non riportato · il pivot-shift è un esame clinico con variabilità fra esaminatori.",perte:"Tocca le tue suture meniscali nell'intervento al crociato: il messaggio pratico è ispezionare sempre il compartimento postero-mediale, e non so se già lo fai di routine. Ma il dato è debole (50 pazienti, un centro, 14 casi) e l'incidenza del 28% ha un intervallo da 18% a 42% (calcolo mio). Non muove alcuna tensione."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Bone Joint J",h:"TKA robotica: cambiare due fenotipi CPAK, recupero precoce minore",v:"Coorte retrospettiva multicentrica di 297 TKA robotiche: il 30,6% resta nello stesso fenotipo CPAK, il 62,3% si sposta di uno, il 6,4% (19 pazienti) di due. Chi si sposta di due ha un miglioramento dell'Oxford Knee Score minore a 3 mesi (p=0,008) e a 6 mesi (p=0,036); con una deviazione della LDFA oltre 4° dal nativo il miglioramento è il più basso (7,14, DS 9,9 a 3 mesi; 10,95, DS 7,0 a 6 mesi). Intervalli di confidenza non riportati nell'abstract.",ax:"Zaidi, Goplen, Akbarshahi, MacDessi, Petterwood, McEwen, Munro, Monk",date:"ott 2026",meta:"coorte retrospettiva multicentrica, 297 TKA robotiche, OKS a 3, 6 e 12 mesi · [III per disegno]",pmid:'42853086',doi:'10.1302/0301-620X.108B10.BJJ-2025-1378.R2',journal:"The bone & joint journal",authors:"Zaidi F, Goplen CM, Akbarshahi M, MacDessi SJ, Petterwood J, McEwen P, Munro JT, Monk AP",design:"Coorte retrospettiva multicentrica (Università di Auckland, Nuova Zelanda, afferenza del primo autore) di artroprotesi totali primarie con assistenza robotica: radiografie dell'arto in carico pre e postoperatorie standardizzate (LDFA, MPTA); classificazione CPAK pre e postoperatoria da HKA aritmetico e obliquità della linea articolare; Oxford Knee Score al basale e a 3, 6 e 12 mesi; analisi esplorativa dell'effetto isolato dei cambi di LDFA e MPTA. Piattaforma robotica, impianto e filosofia di allineamento non riportati nell'abstract. Testo completo non aperto.",pop:"297 pazienti; età, sesso e BMI non riportati nell'abstract. Fenotipo CPAK preoperatorio più frequente: tipo II 30,0% (89), poi tipo I 27,6% (82); postoperatorio: tipo V 30,0% (89), poi IV e II. Follow-up: 12 mesi.",results:"Stesso fenotipo CPAK 30,6% (91), spostamento di una classe 62,3% (185), di due classi 6,4% (19); la somma dei tre gruppi è 295 su 297, due pazienti non spiegati nell'abstract. Chi si sposta di due classi mostra un miglioramento dell'OKS minore a 3 mesi (p=0,008) e a 6 mesi (p=0,036) rispetto a chi resta nello stesso fenotipo. Variazione della LDFA oltre 4° dal nativo: miglioramento medio dell'OKS di 7,14 (DS 9,9) a 3 mesi e 10,95 (DS 7,0) a 6 mesi, il più basso di tutti i gruppi. Risultati a 12 mesi, dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori (analisi esplorativa): alterare l'allineamento coronale di due classi CPAK dopo TKA robotica si associa a un OKS inferiore a 3 e 6 mesi, ma su un sottogruppo piccolo (n=19) che richiede conferma; una deviazione femorale oltre 4° dal nativo sembra pesare più delle variazioni tibiali equivalenti.",limits:"Sottogruppo di 19 pazienti, analisi dichiarata esplorativa dagli autori · retrospettivo, nessuna correzione per confondenti nell'abstract (deformità preoperatoria, correzione intenzionale, BMI) · differenze a 3 e 6 mesi, a 12 mesi non riportate · valori e intervalli di confidenza assenti · robot, impianto e target di allineamento non riportati.",perte:"Per la tua VELYS: l'allineamento personalizzato (CPAK) è il tema, ma l'abstract non nomina né la piattaforma robotica né il target di allineamento, quindi non so se il dato si applichi al tuo flusso di lavoro. È un'associazione su 19 pazienti, non una prova che restare nel fenotipo nativo migliori l'esito. Non cambia la pratica e non muove alcuna tensione."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Bone Joint J",h:"TKA non cementata, polietilene reticolato: l'usura si ferma dopo 5 anni",v:"RCT in doppio cieco su 96 TKA non cementate (Triathlon CR a inserto fisso), radiostereometria a 10 anni: con il polietilene altamente reticolato l'usura mediale resta 0,15 → 0,13 mm da 5 a 10 anni, con il convenzionale sale 0,22 → 0,46 mm. Migrazione tibiale (MTPM) 0,99 mm (IC 95% 0,83-1,18) contro 1,05 mm (0,87-1,24); femorale 1,16 mm (0,99-1,35) contro 1,04 mm (0,87-1,22). Differenza di usura con intervallo di confidenza non riportata nell'abstract.",ax:"de Ridder, Kaptein, Pijls, Nelissen, Pasma, Oomen, Kaptijn",date:"ott 2026",meta:"RCT in doppio cieco, 96 TKA, radiostereometria a 10 anni · [I per disegno]",pmid:'42853089',doi:'10.1302/0301-620X.108B10.BJJ-2026-0426.R1',journal:"The bone & joint journal",authors:"de Ridder R, Kaptein BL, Pijls BG, Nelissen RGHH, Pasma JH, Oomen R, Kaptijn HH",design:"RCT in doppio cieco del Reinier Haga Orthopaedic Centre (Zoetermeer, Paesi Bassi) su protesi totale di ginocchio non cementata Triathlon CR a inserto fisso: inserto di polietilene altamente reticolato (HXLPE) contro polietilene convenzionale (PE); usura dell'inserto e migrazione di tibia e femore con radiostereometria model-based fino a 10 anni; PROM prima e al follow-up. Testo completo non aperto: contenuto dall'abstract.",pop:"96 TKA; ripartizione fra i gruppi, età, sesso e perdite al follow-up non riportati nell'abstract. Follow-up: 10 anni.",results:"Usura mediale HXLPE: 0,15 mm a 5 anni e 0,13 mm a 10 anni (nessuna progressione); PE: 0,22 mm a 5 anni e 0,46 mm a 10 anni. Migrazione tibiale (MTPM) a 10 anni: HXLPE 0,99 mm (IC 95% 0,83-1,18), PE 1,05 mm (0,87-1,24). Migrazione femorale: HXLPE 1,16 mm (0,99-1,35), PE 1,04 mm (0,87-1,22). Nessuna differenza clinicamente rilevante di migrazione o di PROM a 10 anni. Differenza di usura con IC e p non riportati nell'abstract.",concl:"Gli autori: nessun aumento dell'usura dell'HXLPE dopo i 5 anni, mentre quella del PE continua; dopo la migrazione iniziale i componenti non cementati restano stabili a 10 anni; l'HXLPE è sicuro nella TKA non cementata per usura e migrazione.",limits:"96 protesi, un solo modello e un solo centro · usura e migrazione sono esiti surrogati: non misurano revisioni né sopravvivenza dell'impianto · la differenza di usura (0,13 contro 0,46 mm) non ha IC né p nell'abstract · perdite al follow-up a 10 anni non riportate · i valori radiostereometrici non si trasferiscono ad altri impianti.",perte:"Non è il tuo impianto: il Triathlon è un impianto Stryker (informazione che non è nell'abstract), mentre la tua TKA con VELYS è DePuy Synthes, quindi il dato sull'usura non si trasferisce. Entra perché è un RCT a 10 anni e mostra quanto conti il tipo di polietilene sul lungo periodo. Nessuna tensione si muove."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"J ISAKOS",h:"Notch e slope: nessuna differenza rilevabile fra ginocchia asiatiche e occidentali",v:"Revisione sistematica con meta-analisi di 31 studi RM (2.463 ginocchia, 15 coorti asiatiche e 16 occidentali) con LCA integro, nell'ordine dell'abstract asiatiche contro occidentali: larghezza dell'incisura 20,13 contro 19,86 mm (p=0,77), indice 0,28 contro 0,24 (p=0,45), pendenza tibiale mediale 5,66° contro 6,04° (p=0,67) e laterale 5,73° contro 6,24° (p=0,53), larghezza del LCA 5,20 contro 7,62 mm (p=0,08). Eterogeneità I² 75-100% e intervalli di predizione ampi: gli autori parlano di assenza di differenza rilevabile, non di equivalenza.",ax:"Jia Yi, Chen, Po Hui, Han Dave",date:"ott 2026",meta:"revisione sistematica con meta-analisi, 31 studi, 2.463 ginocchia · [IV per disegno]",pmid:'42855074',doi:'10.1016/j.jisako.2026.101233',journal:"Journal of ISAKOS : joint disorders & orthopaedic sports medicine",authors:"Jia Yi FF, Chen W, Po Hui JH, Han Dave LY",design:"Revisione sistematica con meta-analisi secondo PRISMA 2020, registrata in PROSPERO (CRD420261403854), del National University Hospital di Singapore: quattro banche dati dall'inizio all'11 giugno 2026; studi RM su adulti con LCA integro; sei parametri prespecificati (volume dell'incisura femorale, larghezza e indice dell'incisura, pendenza tibiale mediale e laterale, larghezza del LCA); meta-analisi a effetti casuali a braccio singolo (REML) per coorte e confronto con test Q; meta-regressione per tecnica di misura, età e sesso. Coorti classificate per paese di reclutamento, non per etnia individuale. Testo completo non aperto: contenuto dall'abstract.",pop:"31 studi, 2.463 ginocchia (15 coorti asiatiche, 16 occidentali) di adulti con LCA radiologicamente integro; età e sesso per studio non riportati nell'abstract.",results:"Asiatiche contro occidentali: volume dell'incisura 7,26 contro 7,64 cm (p=0,78); larghezza 20,13 contro 19,86 mm (p=0,77); indice 0,28 contro 0,24 (p=0,45); pendenza mediale 5,66° contro 6,04° (p=0,67); laterale 5,73° contro 6,24° (p=0,53); larghezza del LCA 5,20 contro 7,62 mm (p=0,08). I² 75-100%. La coorte geografica non modera alcun esito (p=0,09-0,82); la tecnica di misura è associata alla pendenza laterale (p=0,03; 44% della varianza), il sesso alla larghezza dell'incisura (β=6,48 mm; p=0,02) e al volume (β=5,34 cm; p=0,04), l'età alle pendenze (β=0,11°/anno; p=0,02 e p<0,01). Nelle coorti asiatiche i maschi hanno un volume maggiore (7,65 contro 5,66 cm; p<0,01). Intervalli di confidenza dei valori aggregati non riportati nell'abstract.",concl:"Gli autori: nessuna differenza statisticamente significativa nella morfologia dell'incisura, nella pendenza tibiale e nella larghezza del LCA fra popolazioni asiatiche e occidentali con LCA integro; vista l'eterogeneità e gli intervalli di predizione ampi, indicano assenza di differenza rilevabile e non equivalenza anatomica.",limits:"Eterogeneità I² 75-100% e intervalli di predizione ampi e sovrapposti: la revisione non può dire che le popolazioni siano uguali · coorti definite per paese, non per etnia · meta-analisi a braccio singolo di studi trasversali con tecniche di misura diverse · la larghezza del LCA (5,20 contro 7,62 mm; p=0,08) differisce di 2,4 mm e la revisione non lo esclude · nessun esito di rottura del LCA.",perte:"Fuori dalla tua tecnica, ma utile al tuo buco dichiarato sul mondo orientale: i valori di riferimento di incisura e pendenza tibiale, che contano per lo slope e per il rischio di rottura, non risultano diversi fra Asia e Occidente nella letteratura disponibile, con la cautela dell'eterogeneità. Nessuna tensione si muove."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"J Orthop Case Rep",h:"OATS nei difetti ICRS IV dei giovani: buoni punteggi a 18 mesi",v:"Coorte prospettica di 38 pazienti di 15-40 anni con difetto osteocondrale ICRS grado IV isolato di 2-4 cm² trattati con OATS (35 seguiti a 18 mesi): Lysholm 50,29 ± 10,90 → 93,03 ± 4,11, IKDC 48,29 ± 9,45 → 91,24 ± 4,55, Tegner 2,40 ± 0,60 → 8,71 ± 0,75 (p<0,001). Alla RM integrazione in tutti, superficie congruente nel 91,4% e cistica o delaminazione nell'8,6%; nessun fallimento né complicanza del sito donatore.",ax:"Kumar, Dhankhar, Devgan, Singh, Devgan, Aggarwal",date:"ott 2026",meta:"coorte prospettica a braccio singolo, 38 pazienti (35 a 18 mesi) · [IV per disegno]",pmid:'42851794',doi:'10.13107/jocr.2026.v16.i10.8296',journal:"Journal of orthopaedic case reports",authors:"Kumar V, Dhankhar S, Devgan R, Singh A, Devgan A, Aggarwal C",design:"Coorte prospettica monocentrica a braccio singolo (Post Graduate Institute of Medical Sciences, Rohtak, Haryana, India, afferenza del primo autore): pazienti di 15-40 anni con difetto osteocondrale ICRS grado IV isolato di 2,0-4,0 cm² trattati con trapianto osteocondrale autologo (OATS); Lysholm, IKDC soggettivo e Tegner prima e a 6, 12 e 18 mesi; RM seriate per integrazione dell'innesto, allineamento della superficie e degenerazione. Testo completo non aperto: contenuto dall'abstract.",pop:"38 pazienti arruolati, 35 con follow-up a 18 mesi (3 persi, 7,9%); età media 25,8 ± 5,6 anni; 76,3% maschi; sede del difetto non riportata nell'abstract.",results:"A 18 mesi (p<0,001 per tutte): Lysholm da 50,29 ± 10,90 a 93,03 ± 4,11; IKDC da 48,29 ± 9,45 a 91,24 ± 4,55; Tegner da 2,40 ± 0,60 a 8,71 ± 0,75. RM: guarigione dell'innesto in tutti; superficie congruente nel 91,4% (32 su 35; IC 95% di Wilson 77,6-97,0%, calcolo mio), degenerazione cistica o delaminazione nell'8,6% (3 su 35). Nessun fallimento dell'innesto né complicanza del sito donatore. Intervalli di confidenza delle differenze dei punteggi non riportati nell'abstract.",concl:"Gli autori: l'OATS ha dato guadagni funzionali significativi e duraturi, con integrazione costante dell'innesto, in giovani selezionati con lesione isolata ICRS IV di dimensioni moderate, e si conferma come opzione di preservazione articolare.",limits:"Nessun gruppo di confronto (microfratture, AMIC, condrociti): il miglioramento prima-dopo non attribuisce il merito alla tecnica · 18 mesi sono pochi per un trapianto osteocondrale · il Tegner medio finale, 8,71 ± 0,75, è vicino al massimo della scala e l'abstract non lo discute · 3 pazienti persi su 38 · un solo centro · lettura delle RM (cieca o no) e definizione di fallimento non riportate.",perte:"Non è una tua tecnica (AMIC con Chondro-Gide, AutoCart): l'OATS è un'alternativa per difetti nella stessa fascia di dimensioni in cui usi l'AMIC, ma qui non c'è alcun confronto né con l'AMIC né con l'AutoCart. T5 (minced cartilage) non si muove."}];
var SUGGQ=[{"k": "kol", "n": "M. L. Nault (CHU Sainte-Justine e Université de Montréal, Canada)", "w": "Canada: ultima autrice dello studio di oggi sul LET aggiunto al LCA nei pazienti pediatrici (PMID 42852835; afferenza letta nei metadati PubMed; nome per esteso non riportato nei metadati). Corrispondenza tecnica con il tuo LET su tutti i LCA e con la fascia dai 14 anni. Sostituisce Jingbin Zhou (9 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Oggi, sabato 10 ottobre, nove lavori, nessuna scheda rossa e una arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida nel perimetro. Il lavoro del giorno, arancione, è una serie della Mayo Clinic su cento ricostruzioni del crociato con tendine quadricipitale, un innesto vicino al tuo ma non identico. A nove mesi la forza del quadricipite è al settantasette-ottantuno per cento dell'altra gamba, quella dei flessori al novantotto-cento, eppure a circa due anni il punteggio Lysholm medio è novanta virgola sette e l'IKDC settantasette virgola otto. La forza isometrica a tre mesi è associata all'IKDC a due anni, e chi raggiunge una soglia di sintomi accettabile ha di solito già a tre mesi un indice del sessanta-settanta per cento. Mette in discussione una soglia del novanta per cento come cancello unico di rientro, ma è una serie senza confronto, senza intervalli di confidenza nell'abstract, con punteggi e non rotture, e non dice se c'era il LET. Tra le altre schede: una coorte di Montréal su settanta ragazzi non trova differenze nella camminata a quattro mesi fra crociato con e senza LET, ma a quattro mesi non si escludono effetti tardivi e l'abstract non dice né innesto né tecnica. Una coorte coreana su sessantasette pazienti trova un equilibrio dinamico migliore a tre mesi con la ricostruzione dell'ALL, con un p vicino al limite e senza dimensioni dell'effetto; è un'ALL con innesto, non il tuo Lemaire. Negli adolescenti operati di MPFL un punteggio ACL-RSI da cinquantanove virgola due si associa al rientro, ma la soglia non è validata fuori dal campione. Una serie indiana su cinquanta crociati trova lesioni ramp nel ventotto per cento, e la risonanza ne manca quasi la metà; i casi sono quattordici. Una coorte retrospettiva multicentrica di duecentonovantasette protesi robotiche associa lo spostamento di due fenotipi CPAK a un recupero minore a tre e sei mesi, ma sono diciannove pazienti e il robot non è nominato. Completano un RCT a dieci anni sul polietilene reticolato in una protesi non cementata che non è la tua, una meta-analisi che non trova differenze rilevabili di incisura e pendenza tibiale fra ginocchia asiatiche e occidentali, con eterogeneità elevata, e una coorte senza confronto sul trapianto osteocondrale. Per le proposte da seguire oggi il nome è M. L. Nault, di Montréal, per il LET nel crociato dei giovani.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, sabato 10 ottobre: nove lavori, una scheda arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Una serie della Mayo Clinic su cento ricostruzioni del crociato con tendine quadricipitale, un innesto vicino al tuo ma non identico. A nove mesi la forza del quadricipite è al settantasette-ottantuno per cento dell'altra gamba."}, {"chi": "B", "t": "Quindi sotto la soglia del novanta per cento che si usa per il rientro."}, {"chi": "A", "t": "Sì, in media. Eppure a circa due anni Lysholm novanta virgola sette e IKDC settantasette virgola otto. E la forza a tre mesi è associata all'IKDC a due anni."}, {"chi": "B", "t": "Quindi per la tua soglia cosa cambia?"}, {"chi": "A", "t": "Mette in discussione il novanta per cento come cancello unico, ma non ne propone uno nuovo. È una serie senza confronto, con punteggi e non rotture, e non dice se c'era il LET."}, {"chi": "B", "t": "E sul LET c'è qualcosa oggi?"}, {"chi": "A", "t": "Una coorte di Montréal su settanta ragazzi: a quattro mesi la camminata non cambia fra crociato con e senza LET. Ma quattro mesi sono pochi e l'abstract non dice né innesto né tecnica."}, {"chi": "B", "t": "E le lesioni ramp?"}, {"chi": "A", "t": "Una serie indiana su cinquanta crociati: ramp nel ventotto per cento, e la risonanza ne manca quasi la metà. I casi sono quattordici, quindi le percentuali sono imprecise."}, {"chi": "B", "t": "Per la tua VELYS?"}, {"chi": "A", "t": "Una coorte retrospettiva di duecentonovantasette protesi robotiche associa lo spostamento di due fenotipi CPAK a un recupero minore a tre e sei mesi. Sono diciannove pazienti e il robot non è nominato."}, {"chi": "B", "t": "Quindi nessuna tensione chiusa oggi, ma il criterio di rientro riceve un altro dato. E la proposta da seguire?"}, {"chi": "A", "t": "M. L. Nault, di Montréal, per il LET nel crociato dei giovani."}];
